-- Z-Girl v3.2 Institutional Partner Pipeline & Contract Operations
-- Pre-contract acquisition, proposal, follow-up, and governed handoff into v3.1 institutional workflows.
-- Institutional/business contacts and administrative deal data only. No participant reflection or youth case data belongs here.

create table if not exists public.zgirl_partner_opportunities (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null references public.zgirl_institutions(id) on delete cascade,
  existing_license_id uuid references public.zgirl_institution_licenses(id) on delete set null,
  opportunity_code text not null unique,
  opportunity_type text not null check (opportunity_type in ('pilot','annual','multisite','train_the_trainer','other')),
  contract_path text not null default 'initial_contract' check (contract_path in ('initial_contract','expansion','train_the_trainer_addendum')),
  stage text not null default 'identified' check (stage in ('identified','outreach','discovery','fit_review','qualified','proposal','negotiation','agreement','approval','converted','nurture','closed_lost')),
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  owner_name text check (owner_name is null or char_length(owner_name) <= 120),
  source text check (source is null or char_length(source) <= 160),
  strategic_need text check (strategic_need is null or char_length(strategic_need) <= 1200),
  use_case text check (use_case is null or char_length(use_case) <= 1200),
  estimated_value_cents bigint check (estimated_value_cents is null or estimated_value_cents between 0 and 100000000000),
  currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  probability_percent integer not null default 10 check (probability_percent between 0 and 100),
  target_decision_date date,
  target_start_date date,
  closed_reason text check (closed_reason is null or char_length(closed_reason) <= 600),
  handoff_proposal_id uuid,
  handoff_license_id uuid references public.zgirl_institution_licenses(id) on delete set null,
  handoff_agreement_id uuid references public.zgirl_institution_agreements(id) on delete set null,
  handoff_workflow_id uuid references public.zgirl_institution_workflows(id) on delete set null,
  handoff_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists zgirl_partner_opportunities_stage_idx on public.zgirl_partner_opportunities(stage,priority,updated_at desc);
create index if not exists zgirl_partner_opportunities_org_idx on public.zgirl_partner_opportunities(institution_id,updated_at desc);
create unique index if not exists zgirl_partner_opportunities_open_path_unique on public.zgirl_partner_opportunities(institution_id,contract_path) where stage not in ('converted','closed_lost');

create table if not exists public.zgirl_partner_contacts (
  id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.zgirl_partner_opportunities(id) on delete cascade,
  full_name text not null check (char_length(full_name) between 2 and 160), role_title text check (role_title is null or char_length(role_title) <= 160),
  email text check (email is null or char_length(email) <= 254), phone text check (phone is null or char_length(phone) <= 60),
  decision_role text not null default 'other' check (decision_role in ('champion','decision_maker','procurement','legal','implementation','finance','other')),
  status text not null default 'active' check (status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists zgirl_partner_contacts_opp_idx on public.zgirl_partner_contacts(opportunity_id,status,updated_at desc);

create table if not exists public.zgirl_partner_activities (
  id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.zgirl_partner_opportunities(id) on delete cascade,
  activity_type text not null check (activity_type in ('email','call','meeting','note','follow_up','proposal','decision','system')),
  direction text not null default 'internal' check (direction in ('inbound','outbound','internal')),
  summary text not null check (char_length(summary) between 2 and 1600), actor_name text check (actor_name is null or char_length(actor_name) <= 120),
  occurred_at timestamptz not null default now(), created_at timestamptz not null default now()
);
create index if not exists zgirl_partner_activities_opp_idx on public.zgirl_partner_activities(opportunity_id,occurred_at desc);

create table if not exists public.zgirl_partner_proposals (
  id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.zgirl_partner_opportunities(id) on delete cascade,
  proposal_code text not null unique, proposal_type text not null check (proposal_type in ('pilot','annual','multisite','train_the_trainer','expansion')),
  version integer not null default 1 check (version between 1 and 999),
  status text not null default 'draft' check (status in ('draft','internal_review','sent','revised','accepted','declined','expired','withdrawn')),
  title text not null check (char_length(title) between 2 and 220), scope_summary text check (scope_summary is null or char_length(scope_summary) <= 2400),
  proposed_value_cents bigint check (proposed_value_cents is null or proposed_value_cents between 0 and 100000000000),
  currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'), reference text check (reference is null or char_length(reference) <= 180),
  sent_at timestamptz, expires_at date, decision_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(opportunity_id,version)
);
create index if not exists zgirl_partner_proposals_opp_idx on public.zgirl_partner_proposals(opportunity_id,status,updated_at desc);

do $$ begin
  if not exists(select 1 from pg_constraint where conname='zgirl_partner_opportunities_handoff_proposal_id_fkey') then
    alter table public.zgirl_partner_opportunities add constraint zgirl_partner_opportunities_handoff_proposal_id_fkey foreign key (handoff_proposal_id) references public.zgirl_partner_proposals(id) on delete set null;
  end if;
end $$;

create table if not exists public.zgirl_partner_followups (
  id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.zgirl_partner_opportunities(id) on delete cascade,
  action_text text not null check (char_length(action_text) between 2 and 500), due_at timestamptz not null,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')), owner_name text check (owner_name is null or char_length(owner_name) <= 120),
  status text not null default 'open' check (status in ('open','completed','cancelled')), completed_at timestamptz,
  completion_note text check (completion_note is null or char_length(completion_note) <= 600), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists zgirl_partner_followups_due_idx on public.zgirl_partner_followups(status,due_at,priority);
create index if not exists zgirl_partner_followups_opp_idx on public.zgirl_partner_followups(opportunity_id,status,due_at);

alter table public.zgirl_partner_opportunities enable row level security;
alter table public.zgirl_partner_contacts enable row level security;
alter table public.zgirl_partner_activities enable row level security;
alter table public.zgirl_partner_proposals enable row level security;
alter table public.zgirl_partner_followups enable row level security;
revoke all on public.zgirl_partner_opportunities,public.zgirl_partner_contacts,public.zgirl_partner_activities,public.zgirl_partner_proposals,public.zgirl_partner_followups from anon,authenticated;

alter table public.zgirl_institution_workflows drop constraint if exists zgirl_institution_workflows_workflow_type_check;
alter table public.zgirl_institution_workflows add constraint zgirl_institution_workflows_workflow_type_check check (workflow_type in ('initial_contract','renewal','expansion','change_order','train_the_trainer_addendum'));

create or replace function public.zgirl_institution_create_workflow(p_session_token text,p_workflow_id uuid,p_license_id uuid,p_workflow_type text,p_agreement_id uuid,p_requested_effective_date date,p_requested_expires_at date,p_requested_seat_limit integer,p_requested_site_limit integer,p_requested_trainer_limit integer,p_requested_profiles text[],p_requested_levels text[],p_target_start_date date,p_request_reference text)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare v_l public.zgirl_institution_licenses%rowtype; v_id uuid; v_code text; v_seat integer; v_site integer; v_trainer integer; v_profiles text[]; v_levels text[]; v_eff date; v_exp date; v_seats_used integer; v_sites_used integer; v_trainers_used integer;
begin
 perform private.zgirl_credential_require_session(p_session_token); select * into v_l from public.zgirl_institution_licenses where id=p_license_id;
 if v_l.id is null then raise exception 'license_not_found'; end if; if v_l.status='closed' then raise exception 'license_not_releasable'; end if;
 if p_workflow_type not in ('initial_contract','renewal','expansion','change_order','train_the_trainer_addendum') then raise exception 'invalid_workflow_type'; end if;
 if p_workflow_type='initial_contract' and v_l.status not in ('draft','pending') then raise exception 'initial_contract_requires_draft_license'; end if;
 if p_agreement_id is not null and not exists(select 1 from public.zgirl_institution_agreements where id=p_agreement_id and institution_id=v_l.institution_id and (license_id is null or license_id=p_license_id)) then raise exception 'invalid_workflow_agreement'; end if;
 v_seat:=coalesce(p_requested_seat_limit,v_l.seat_limit); v_site:=coalesce(p_requested_site_limit,v_l.site_limit); v_trainer:=coalesce(p_requested_trainer_limit,v_l.trainer_limit); v_profiles:=coalesce(p_requested_profiles,v_l.allowed_profiles); v_levels:=coalesce(p_requested_levels,v_l.allowed_credential_levels);
 v_eff:=coalesce(p_requested_effective_date,case when p_workflow_type='renewal' then v_l.expires_at+1 else v_l.effective_date end); v_exp:=coalesce(p_requested_expires_at,case when p_workflow_type='renewal' then (v_l.expires_at+interval '1 year')::date else v_l.expires_at end);
 if v_seat<1 or v_site<1 or v_trainer<0 then raise exception 'invalid_workflow_limits'; end if; if v_profiles is null or cardinality(v_profiles)=0 or not(v_profiles <@ array['general','edu','faith','athlete']::text[]) then raise exception 'invalid_profiles'; end if; if v_levels is null or cardinality(v_levels)=0 or not(v_levels <@ array['authorized_facilitator','authorized_lead_facilitator','institutional_trainer']::text[]) then raise exception 'invalid_levels'; end if; if v_eff is not null and v_exp is not null and v_exp<=v_eff then raise exception 'invalid_workflow_term'; end if;
 select count(*) into v_seats_used from public.zgirl_institution_seat_allocations where license_id=p_license_id and status<>'released'; select count(distinct site_id) into v_sites_used from public.zgirl_institution_seat_allocations where license_id=p_license_id and status<>'released' and site_id is not null; select count(*) into v_trainers_used from public.zgirl_institution_seat_allocations where license_id=p_license_id and status<>'released' and seat_role='institutional_trainer'; if v_seat<v_seats_used then raise exception 'seat_limit_below_usage'; end if; if v_site<v_sites_used then raise exception 'site_limit_below_usage'; end if; if v_trainer<v_trainers_used then raise exception 'trainer_limit_below_usage'; end if;
 if p_workflow_id is null then v_code:='ZG-WF-'||extract(year from current_date)::int||'-'||upper(substr(replace(extensions.gen_random_uuid()::text,'-',''),1,10)); insert into public.zgirl_institution_workflows(institution_id,license_id,agreement_id,workflow_code,workflow_type,status,requested_effective_date,requested_expires_at,requested_seat_limit,requested_site_limit,requested_trainer_limit,requested_profiles,requested_credential_levels,target_start_date,request_reference) values(v_l.institution_id,p_license_id,p_agreement_id,v_code,p_workflow_type,'evidence_build',v_eff,v_exp,v_seat,v_site,v_trainer,v_profiles,v_levels,p_target_start_date,nullif(trim(p_request_reference),'')) returning id into v_id; perform private.zgirl_seed_institution_workflow_gates(v_id); perform private.zgirl_refresh_institution_evidence(v_id); insert into public.zgirl_institution_license_events(institution_id,license_id,event_type,summary) values(v_l.institution_id,p_license_id,'workflow_created','Institution workflow created: '||v_code||' ('||p_workflow_type||')');
 else update public.zgirl_institution_workflows set agreement_id=p_agreement_id,workflow_type=p_workflow_type,requested_effective_date=v_eff,requested_expires_at=v_exp,requested_seat_limit=v_seat,requested_site_limit=v_site,requested_trainer_limit=v_trainer,requested_profiles=v_profiles,requested_credential_levels=v_levels,target_start_date=p_target_start_date,request_reference=nullif(trim(p_request_reference),''),updated_at=now() where id=p_workflow_id and license_id=p_license_id and status in ('draft','evidence_build','approvals_pending','agreement_pending','release_review') returning id into v_id; if v_id is null then raise exception 'workflow_locked'; end if; perform private.zgirl_seed_institution_workflow_gates(v_id); perform private.zgirl_refresh_institution_evidence(v_id); insert into public.zgirl_institution_license_events(institution_id,license_id,event_type,summary) values(v_l.institution_id,p_license_id,'workflow_updated','Institution workflow updated'); end if; return v_id;
end; $$;

create or replace function public.zgirl_partner_save_opportunity(p_session_token text,p_opportunity_id uuid,p_institution_id uuid,p_existing_license_id uuid,p_opportunity_type text,p_contract_path text,p_stage text,p_priority text,p_owner_name text,p_source text,p_strategic_need text,p_use_case text,p_estimated_value_cents bigint,p_currency text,p_probability_percent integer,p_target_decision_date date,p_target_start_date date,p_closed_reason text)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare v_id uuid; v_code text;
begin perform private.zgirl_credential_require_session(p_session_token); if not exists(select 1 from public.zgirl_institutions where id=p_institution_id) then raise exception 'institution_not_found'; end if; if p_existing_license_id is not null and not exists(select 1 from public.zgirl_institution_licenses where id=p_existing_license_id and institution_id=p_institution_id and status<>'closed') then raise exception 'invalid_pipeline_license'; end if; if p_opportunity_type not in ('pilot','annual','multisite','train_the_trainer','other') then raise exception 'invalid_opportunity_type'; end if; if p_contract_path not in ('initial_contract','expansion','train_the_trainer_addendum') then raise exception 'invalid_contract_path'; end if; if p_contract_path<>'initial_contract' and p_existing_license_id is null then raise exception 'existing_license_required'; end if; if p_stage not in ('identified','outreach','discovery','fit_review','qualified','proposal','negotiation','agreement','approval','converted','nurture','closed_lost') then raise exception 'invalid_pipeline_stage'; end if; if p_priority not in ('low','normal','high','urgent') then raise exception 'invalid_priority'; end if; if p_estimated_value_cents is not null and (p_estimated_value_cents<0 or p_estimated_value_cents>100000000000) then raise exception 'invalid_pipeline_value'; end if; if coalesce(p_currency,'USD') !~ '^[A-Z]{3}$' then raise exception 'invalid_currency'; end if; if p_probability_percent is null or p_probability_percent<0 or p_probability_percent>100 then raise exception 'invalid_probability'; end if; if char_length(coalesce(p_strategic_need,''))>1200 or char_length(coalesce(p_use_case,''))>1200 then raise exception 'invalid_pipeline_summary'; end if; if p_stage='closed_lost' and nullif(trim(coalesce(p_closed_reason,'')),'') is null then raise exception 'closed_reason_required'; end if;
 if p_opportunity_id is null then v_code:='ZG-OPP-'||extract(year from current_date)::int||'-'||upper(substr(replace(extensions.gen_random_uuid()::text,'-',''),1,10)); insert into public.zgirl_partner_opportunities(institution_id,existing_license_id,opportunity_code,opportunity_type,contract_path,stage,priority,owner_name,source,strategic_need,use_case,estimated_value_cents,currency,probability_percent,target_decision_date,target_start_date,closed_reason) values(p_institution_id,p_existing_license_id,v_code,p_opportunity_type,p_contract_path,p_stage,p_priority,nullif(trim(p_owner_name),''),nullif(trim(p_source),''),nullif(trim(p_strategic_need),''),nullif(trim(p_use_case),''),p_estimated_value_cents,upper(coalesce(p_currency,'USD')),p_probability_percent,p_target_decision_date,p_target_start_date,nullif(trim(p_closed_reason),'')) returning id into v_id; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary,actor_name) values(v_id,'system','internal','Partner opportunity created',nullif(trim(p_owner_name),''));
 else update public.zgirl_partner_opportunities set existing_license_id=p_existing_license_id,opportunity_type=p_opportunity_type,contract_path=p_contract_path,stage=p_stage,priority=p_priority,owner_name=nullif(trim(p_owner_name),''),source=nullif(trim(p_source),''),strategic_need=nullif(trim(p_strategic_need),''),use_case=nullif(trim(p_use_case),''),estimated_value_cents=p_estimated_value_cents,currency=upper(coalesce(p_currency,'USD')),probability_percent=p_probability_percent,target_decision_date=p_target_decision_date,target_start_date=p_target_start_date,closed_reason=nullif(trim(p_closed_reason),''),updated_at=now() where id=p_opportunity_id and institution_id=p_institution_id and handoff_workflow_id is null returning id into v_id; if v_id is null then raise exception 'opportunity_locked'; end if; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary,actor_name) values(v_id,'system','internal','Partner opportunity updated',nullif(trim(p_owner_name),'')); end if; return v_id; end; $$;

create or replace function public.zgirl_partner_save_contact(p_session_token text,p_contact_id uuid,p_opportunity_id uuid,p_full_name text,p_role_title text,p_email text,p_phone text,p_decision_role text,p_status text)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_id uuid; begin perform private.zgirl_credential_require_session(p_session_token); if not exists(select 1 from public.zgirl_partner_opportunities where id=p_opportunity_id) then raise exception 'opportunity_not_found'; end if; if char_length(trim(coalesce(p_full_name,'')))<2 or char_length(trim(p_full_name))>160 or p_decision_role not in ('champion','decision_maker','procurement','legal','implementation','finance','other') or p_status not in ('active','inactive') then raise exception 'invalid_partner_contact'; end if; if p_contact_id is null then insert into public.zgirl_partner_contacts(opportunity_id,full_name,role_title,email,phone,decision_role,status) values(p_opportunity_id,trim(p_full_name),nullif(trim(p_role_title),''),nullif(lower(trim(p_email)),''),nullif(trim(p_phone),''),p_decision_role,p_status) returning id into v_id; else update public.zgirl_partner_contacts set full_name=trim(p_full_name),role_title=nullif(trim(p_role_title),''),email=nullif(lower(trim(p_email)),''),phone=nullif(trim(p_phone),''),decision_role=p_decision_role,status=p_status,updated_at=now() where id=p_contact_id and opportunity_id=p_opportunity_id returning id into v_id; if v_id is null then raise exception 'partner_contact_not_found'; end if; end if; return v_id; end; $$;

create or replace function public.zgirl_partner_log_activity(p_session_token text,p_opportunity_id uuid,p_activity_type text,p_direction text,p_summary text,p_actor_name text,p_occurred_at timestamptz)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_id uuid; begin perform private.zgirl_credential_require_session(p_session_token); if not exists(select 1 from public.zgirl_partner_opportunities where id=p_opportunity_id) then raise exception 'opportunity_not_found'; end if; if p_activity_type not in ('email','call','meeting','note','follow_up','proposal','decision','system') or p_direction not in ('inbound','outbound','internal') or char_length(trim(coalesce(p_summary,'')))<2 or char_length(trim(p_summary))>1600 then raise exception 'invalid_partner_activity'; end if; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary,actor_name,occurred_at) values(p_opportunity_id,p_activity_type,p_direction,trim(p_summary),nullif(trim(p_actor_name),''),coalesce(p_occurred_at,now())) returning id into v_id; update public.zgirl_partner_opportunities set updated_at=now() where id=p_opportunity_id; return v_id; end; $$;

create or replace function public.zgirl_partner_save_proposal(p_session_token text,p_proposal_id uuid,p_opportunity_id uuid,p_proposal_type text,p_version integer,p_status text,p_title text,p_scope_summary text,p_proposed_value_cents bigint,p_currency text,p_reference text,p_sent_at timestamptz,p_expires_at date)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$ declare v_id uuid; v_code text; begin perform private.zgirl_credential_require_session(p_session_token); if not exists(select 1 from public.zgirl_partner_opportunities where id=p_opportunity_id) then raise exception 'opportunity_not_found'; end if; if p_proposal_type not in ('pilot','annual','multisite','train_the_trainer','expansion') or p_status not in ('draft','internal_review','sent','revised','accepted','declined','expired','withdrawn') or p_version is null or p_version<1 or p_version>999 or char_length(trim(coalesce(p_title,'')))<2 or char_length(trim(p_title))>220 or char_length(coalesce(p_scope_summary,''))>2400 or char_length(coalesce(p_reference,''))>180 then raise exception 'invalid_proposal'; end if; if p_proposed_value_cents is not null and (p_proposed_value_cents<0 or p_proposed_value_cents>100000000000) then raise exception 'invalid_pipeline_value'; end if; if coalesce(p_currency,'USD') !~ '^[A-Z]{3}$' then raise exception 'invalid_currency'; end if; if p_proposal_id is null then v_code:='ZG-PROP-'||extract(year from current_date)::int||'-'||upper(substr(replace(extensions.gen_random_uuid()::text,'-',''),1,10)); insert into public.zgirl_partner_proposals(opportunity_id,proposal_code,proposal_type,version,status,title,scope_summary,proposed_value_cents,currency,reference,sent_at,expires_at,decision_at) values(p_opportunity_id,v_code,p_proposal_type,p_version,p_status,trim(p_title),nullif(trim(p_scope_summary),''),p_proposed_value_cents,upper(coalesce(p_currency,'USD')),nullif(trim(p_reference),''),case when p_status in ('sent','revised','accepted','declined') then coalesce(p_sent_at,now()) else p_sent_at end,p_expires_at,case when p_status in ('accepted','declined') then now() end) returning id into v_id; else update public.zgirl_partner_proposals set proposal_type=p_proposal_type,version=p_version,status=p_status,title=trim(p_title),scope_summary=nullif(trim(p_scope_summary),''),proposed_value_cents=p_proposed_value_cents,currency=upper(coalesce(p_currency,'USD')),reference=nullif(trim(p_reference),''),sent_at=case when p_status in ('sent','revised','accepted','declined') then coalesce(sent_at,p_sent_at,now()) else p_sent_at end,expires_at=p_expires_at,decision_at=case when p_status in ('accepted','declined') then coalesce(decision_at,now()) when p_status in ('draft','internal_review','sent','revised') then null else decision_at end,updated_at=now() where id=p_proposal_id and opportunity_id=p_opportunity_id returning id into v_id; if v_id is null then raise exception 'proposal_not_found'; end if; end if; update public.zgirl_partner_opportunities set stage=case when p_status='accepted' then 'negotiation' when p_status in ('sent','revised') and stage in ('identified','outreach','discovery','fit_review','qualified') then 'proposal' else stage end,estimated_value_cents=coalesce(p_proposed_value_cents,estimated_value_cents),currency=upper(coalesce(p_currency,currency)),updated_at=now() where id=p_opportunity_id; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary) values(p_opportunity_id,'proposal','internal','Proposal '||p_status||': '||trim(p_title)); return v_id; end; $$;

create or replace function public.zgirl_partner_save_followup(p_session_token text,p_followup_id uuid,p_opportunity_id uuid,p_action_text text,p_due_at timestamptz,p_priority text,p_owner_name text)
returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_id uuid; begin perform private.zgirl_credential_require_session(p_session_token); if not exists(select 1 from public.zgirl_partner_opportunities where id=p_opportunity_id) then raise exception 'opportunity_not_found'; end if; if char_length(trim(coalesce(p_action_text,'')))<2 or char_length(trim(p_action_text))>500 or p_due_at is null or p_priority not in ('low','normal','high','urgent') then raise exception 'invalid_followup'; end if; if p_followup_id is null then insert into public.zgirl_partner_followups(opportunity_id,action_text,due_at,priority,owner_name,status) values(p_opportunity_id,trim(p_action_text),p_due_at,p_priority,nullif(trim(p_owner_name),''),'open') returning id into v_id; else update public.zgirl_partner_followups set action_text=trim(p_action_text),due_at=p_due_at,priority=p_priority,owner_name=nullif(trim(p_owner_name),''),updated_at=now() where id=p_followup_id and opportunity_id=p_opportunity_id and status='open' returning id into v_id; if v_id is null then raise exception 'followup_not_found'; end if; end if; return v_id; end; $$;

create or replace function public.zgirl_partner_complete_followup(p_session_token text,p_followup_id uuid,p_completion_note text)
returns boolean language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_opp uuid; v_text text; begin perform private.zgirl_credential_require_session(p_session_token); update public.zgirl_partner_followups set status='completed',completed_at=now(),completion_note=nullif(trim(p_completion_note),''),updated_at=now() where id=p_followup_id and status='open' returning opportunity_id,action_text into v_opp,v_text; if v_opp is null then raise exception 'followup_not_found'; end if; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary) values(v_opp,'follow_up','internal','Completed follow-up: '||v_text); return true; end; $$;

create or replace function public.zgirl_partner_handoff_to_workflow(p_session_token text,p_opportunity_id uuid,p_proposal_id uuid,p_effective_date date,p_expires_at date,p_seat_limit integer,p_site_limit integer,p_trainer_limit integer,p_profiles text[],p_levels text[])
returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare v_o public.zgirl_partner_opportunities%rowtype; v_p public.zgirl_partner_proposals%rowtype; v_license_id uuid; v_agreement_id uuid; v_workflow_id uuid; v_license_type text; v_agreement_type text; v_workflow_type text;
begin perform private.zgirl_credential_require_session(p_session_token); select * into v_o from public.zgirl_partner_opportunities where id=p_opportunity_id for update; if v_o.id is null then raise exception 'opportunity_not_found'; end if; if v_o.handoff_workflow_id is not null then raise exception 'opportunity_already_handed_off'; end if; select * into v_p from public.zgirl_partner_proposals where id=p_proposal_id and opportunity_id=p_opportunity_id; if v_p.id is null then raise exception 'proposal_not_found'; end if; if v_p.status<>'accepted' then raise exception 'accepted_proposal_required'; end if; if p_effective_date is null or p_expires_at is null or p_expires_at<=p_effective_date then raise exception 'invalid_license_term'; end if; if p_seat_limit<1 or p_site_limit<1 or p_trainer_limit<0 then raise exception 'invalid_license_limits'; end if; if p_profiles is null or cardinality(p_profiles)=0 or not(p_profiles <@ array['general','edu','faith','athlete']::text[]) then raise exception 'invalid_profiles'; end if; if p_levels is null or cardinality(p_levels)=0 or not(p_levels <@ array['authorized_facilitator','authorized_lead_facilitator','institutional_trainer']::text[]) then raise exception 'invalid_levels'; end if;
 if v_o.contract_path='initial_contract' then v_license_type:=case v_p.proposal_type when 'pilot' then 'pilot' when 'annual' then 'annual' when 'multisite' then 'multisite' when 'train_the_trainer' then 'train_the_trainer' else null end; if v_license_type is null then raise exception 'invalid_initial_contract_proposal'; end if; v_license_id:=public.zgirl_institution_save_license(p_session_token,null,v_o.institution_id,v_license_type,'draft',p_effective_date,p_expires_at,p_seat_limit,p_site_limit,p_trainer_limit,p_profiles,p_levels,'draft',null); v_agreement_type:=case v_p.proposal_type when 'pilot' then 'pilot' when 'train_the_trainer' then 'train_the_trainer_addendum' else 'annual' end; v_agreement_id:=public.zgirl_institution_save_agreement(p_session_token,null,v_o.institution_id,v_license_id,v_agreement_type,1,'draft',v_p.reference,p_effective_date,p_expires_at,v_p.scope_summary); v_workflow_type:='initial_contract';
 else if v_o.existing_license_id is null then raise exception 'existing_license_required'; end if; v_license_id:=v_o.existing_license_id; if v_o.contract_path='expansion' then v_workflow_type:='expansion'; v_agreement_type:='expansion'; else v_workflow_type:='train_the_trainer_addendum'; v_agreement_type:='train_the_trainer_addendum'; end if; v_agreement_id:=public.zgirl_institution_save_agreement(p_session_token,null,v_o.institution_id,v_license_id,v_agreement_type,1,'draft',v_p.reference,p_effective_date,p_expires_at,v_p.scope_summary); end if;
 v_workflow_id:=public.zgirl_institution_create_workflow(p_session_token,null,v_license_id,v_workflow_type,v_agreement_id,p_effective_date,p_expires_at,p_seat_limit,p_site_limit,p_trainer_limit,p_profiles,p_levels,coalesce(v_o.target_start_date,p_effective_date),'PIPELINE:'||v_o.opportunity_code||':'||v_p.proposal_code); update public.zgirl_partner_opportunities set stage='agreement',handoff_proposal_id=v_p.id,handoff_license_id=v_license_id,handoff_agreement_id=v_agreement_id,handoff_workflow_id=v_workflow_id,handoff_at=now(),updated_at=now() where id=v_o.id; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary,actor_name) values(v_o.id,'system','internal','Accepted proposal handed to governed institutional workflow '||(select workflow_code from public.zgirl_institution_workflows where id=v_workflow_id),v_o.owner_name); return jsonb_build_object('licenseId',v_license_id,'agreementId',v_agreement_id,'workflowId',v_workflow_id,'workflowType',v_workflow_type); end; $$;

create or replace function private.zgirl_sync_partner_from_workflow()
returns trigger language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare v_institution uuid; v_license_type text; begin if old.status is distinct from new.status then update public.zgirl_partner_opportunities set stage=case when new.status='released' then 'converted' when new.status in ('release_review','ready_for_handoff','scheduled') then 'approval' else stage end,updated_at=now() where handoff_workflow_id=new.id; insert into public.zgirl_partner_activities(opportunity_id,activity_type,direction,summary) select id,'system','internal','Governed institutional workflow moved to '||new.status from public.zgirl_partner_opportunities where handoff_workflow_id=new.id; if new.status='released' then select institution_id,license_type into v_institution,v_license_type from public.zgirl_institution_licenses where id=new.license_id; update public.zgirl_institutions set status=case when v_license_type='pilot' then 'pilot' else 'active' end,updated_at=now() where id=v_institution and status in ('prospect','pilot','paused'); end if; end if; return new; end; $$;
drop trigger if exists zgirl_partner_workflow_sync on public.zgirl_institution_workflows;
create trigger zgirl_partner_workflow_sync after update of status on public.zgirl_institution_workflows for each row execute function private.zgirl_sync_partner_from_workflow();

create or replace function public.zgirl_partner_pipeline_dashboard(p_session_token text)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
begin perform private.zgirl_credential_require_session(p_session_token); update public.zgirl_partner_proposals set status='expired',updated_at=now() where status in ('sent','revised') and expires_at is not null and expires_at<current_date; return jsonb_build_object(
 'summary',jsonb_build_object('openOpportunities',(select count(*) from public.zgirl_partner_opportunities where stage not in ('converted','closed_lost')),'fitReview',(select count(*) from public.zgirl_partner_opportunities where stage='fit_review'),'qualified',(select count(*) from public.zgirl_partner_opportunities where stage='qualified'),'proposalsOpen',(select count(*) from public.zgirl_partner_proposals where status in ('draft','internal_review','sent','revised')),'agreementsInProgress',(select count(*) from public.zgirl_partner_opportunities where stage in ('agreement','approval')),'followupsDueToday',(select count(*) from public.zgirl_partner_followups where status='open' and due_at::date=current_date),'followupsOverdue',(select count(*) from public.zgirl_partner_followups where status='open' and due_at<now()),'staleOpen',(select count(*) from public.zgirl_partner_opportunities where stage not in ('converted','closed_lost') and updated_at<now()-interval '14 days'),'converted',(select count(*) from public.zgirl_partner_opportunities where stage='converted'),'pipelineValueCents',coalesce((select sum(estimated_value_cents) from public.zgirl_partner_opportunities where stage not in ('converted','closed_lost')),0),'weightedValueCents',coalesce((select sum((estimated_value_cents*probability_percent)/100) from public.zgirl_partner_opportunities where stage not in ('converted','closed_lost')),0)),
 'institutions',coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from (select id,institution_code,name,institution_type,status,primary_contact_name,primary_contact_email from public.zgirl_institutions where status<>'closed' order by name limit 300)x),'[]'::jsonb),
 'licenses',coalesce((select jsonb_agg(to_jsonb(x) order by x.expires_at) from (select l.id,l.institution_id,i.name institution_name,l.license_code,l.license_type,l.status,l.effective_date,l.expires_at from public.zgirl_institution_licenses l join public.zgirl_institutions i on i.id=l.institution_id where l.status<>'closed' order by l.expires_at limit 300)x),'[]'::jsonb),
 'opportunities',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (select o.*,i.name institution_name,i.institution_type,i.status institution_status,l.license_code existing_license_code,w.workflow_code,w.status workflow_status,a.agreement_code,a.status agreement_status from public.zgirl_partner_opportunities o join public.zgirl_institutions i on i.id=o.institution_id left join public.zgirl_institution_licenses l on l.id=o.existing_license_id left join public.zgirl_institution_workflows w on w.id=o.handoff_workflow_id left join public.zgirl_institution_agreements a on a.id=o.handoff_agreement_id order by o.updated_at desc limit 400)x),'[]'::jsonb),
 'contacts',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (select * from public.zgirl_partner_contacts order by updated_at desc limit 800)x),'[]'::jsonb),
 'activities',coalesce((select jsonb_agg(to_jsonb(x) order by x.occurred_at desc) from (select * from public.zgirl_partner_activities order by occurred_at desc limit 1200)x),'[]'::jsonb),
 'proposals',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (select * from public.zgirl_partner_proposals order by updated_at desc limit 600)x),'[]'::jsonb),
 'followups',coalesce((select jsonb_agg(to_jsonb(x) order by x.due_at) from (select * from public.zgirl_partner_followups order by case when status='open' then 0 else 1 end,due_at limit 800)x),'[]'::jsonb)); end; $$;

revoke all on function public.zgirl_partner_save_opportunity(text,uuid,uuid,uuid,text,text,text,text,text,text,text,text,bigint,text,integer,date,date,text) from public;
revoke all on function public.zgirl_partner_save_contact(text,uuid,uuid,text,text,text,text,text,text) from public;
