revoke all on function public.zgirl_partner_save_followup(text,uuid,uuid,text,timestamptz,text,text) from public;
revoke all on function public.zgirl_partner_complete_followup(text,uuid,text) from public;
revoke all on function public.zgirl_partner_handoff_to_workflow(text,uuid,uuid,date,date,integer,integer,integer,text[],text[]) from public;
revoke all on function public.zgirl_partner_pipeline_dashboard(text) from public;
grant execute on function public.zgirl_partner_save_opportunity(text,uuid,uuid,uuid,text,text,text,text,text,text,text,text,bigint,text,integer,date,date,text) to anon,authenticated;
grant execute on function public.zgirl_partner_save_contact(text,uuid,uuid,text,text,text,text,text,text) to anon,authenticated;
grant execute on function public.zgirl_partner_log_activity(text,uuid,text,text,text,text,timestamptz) to anon,authenticated;
grant execute on function public.zgirl_partner_save_proposal(text,uuid,uuid,text,integer,text,text,text,bigint,text,text,timestamptz,date) to anon,authenticated;
grant execute on function public.zgirl_partner_save_followup(text,uuid,uuid,text,timestamptz,text,text) to anon,authenticated;
